            <tr><td className="px-3 py-2 text-xs">東北</td><td className="px-3 py-2 text-xs">岩手県</td><td className="px-3 py-2 text-xs">釜石市市街地</td><td className="px-3 py-2 text-xs">市街地出没</td><td className="px-3 py-2 text-xs">市街地における目撃（※5）</td></tr>
